// Get next clip from Ready_Clips sheet
// Returns oldest unposted clip
const sheetId = $env.GOOGLE_SHEET_ID;

// This would be a Google Sheets read - simplified for workflow
// In practice, use Google Sheets node to read
return { sheetId, range: 'Ready_Clips!A2:M' };

// Find first unposted clip (status === 'ready_to_post')
const rows = $json.values || [];

for (const row of rows) {
  // Columns: A=clip_id, B=vod_id, C=streamer, D=game, E=start_time, F=end_time,
  // G=title, H=reason, I=score, J=video_path, K=video_url, L=file_size_mb, M=status
  if (row[12] === 'ready_to_post') {
    return {
      clip_id: row[0],
      vod_id: row[1],
      streamer: row[2],
      game: row[3],
      start_time: row[4],
      end_time: row[5],
      title: row[6],
      reason: row[7],
      score: row[8],
      video_path: row[9],
      video_url: row[10],
      file_size_mb: row[11],
      row_index: rows.indexOf(row) + 2 // 1-indexed + header
    };
  }
}

return { error: 'No clips ready to post' };

// Generate caption with hashtags
const { streamer, game, title, reason, clip_id, file_size_mb } = $json;

const pillarHashtags = {
  'Insane Plays': '#clutch #outplay #insane #gamingclips #proplay',
  'Funny Moments': '#funny #fail #ragemoment #gamingfunny #lol',
  'Reactions': '#reaction #streamer #gamingreaction #priceless',
  'Tips': '#gamingtips #howto #protip #improve #guide'
};

// Determine pillar from reason/title
let pillar = 'Insane Plays';
const text = (title + ' ' + reason).toLowerCase();
if (text.includes('funny') || text.includes('fail') || text.includes('lol')) pillar = 'Funny Moments';
else if (text.includes('react') || text.includes('wtf') || text.includes('omg')) pillar = 'Reactions';
else if (text.includes('tip') || text.includes('how') || text.includes('guide')) pillar = 'Tips';

const hashtags = pillarHashtags[pillar] || pillarHashtags['Insane Plays'];

const caption = `${title}

${reason}

Streamer: @${streamer}
Game: ${game}

${hashtags} #${game.replace(/\s+/g, '')} #${streamer} #fyp #gaming`;

const fileSizeBytes = Math.round((file_size_mb || 0) * 1024 * 1024);
const chunkSize = 10485760; // 10 MB
const totalChunkCount = Math.max(1, Math.ceil(fileSizeBytes / chunkSize));

return { ...$json, caption, pillar, file_size_bytes: fileSizeBytes, chunk_size: chunkSize, total_chunk_count: totalChunkCount };

// Prepare video file for upload; carry publish_id and upload_url forward
const data = $json.data || $json;
const { video_path: vp, publish_id, upload_url } = data;

const fs = require('fs');
if (!fs.existsSync(vp)) {
  throw new Error('Video file not found: ' + vp);
}

const stats = fs.statSync(vp);
const fileSizeBytes = stats.size; // actual bytes on disk

return {
  ...$json,
  video_path: vp,
  publish_id,
  upload_url,
  file_size_bytes,
};

// Update sheet: mark as posted
const { row_index, clip_id, publish_id } = $json;

return {
  sheetId: $env.GOOGLE_SHEET_ID,
  range: `Ready_Clips!M${row_index}:N${row_index}`,
  values: [[
    'posted',
    new Date().toISOString(),
    publish_id
  ]]
};

// Log to analytics sheet
const { clip_id, streamer, game, pillar, caption, publish_id } = $json;

return {
  sheetId: $env.GOOGLE_SHEET_ID,
  range: 'Analytics!A:H',
  values: [[
    new Date().toISOString(),
    clip_id,
    streamer,
    game,
    pillar,
    publish_id,
    'posted',
    0 // initial views
  ]]
};

// Notify Discord
const { clip_id, streamer, game, pillar, caption, video_url } = $json;

return {
  content: `✅ **Posted to TikTok**\n**Clip:** ${clip_id}\n**Streamer:** ${streamer}\n**Game:** ${game}\n**Pillar:** ${pillar}\n**Caption:** ${caption.substring(0, 100)}...\n**Link:** ${video_url}`,
  username: 'Clip Bot'
};
